def numberOfGoodPaths(vals, edges):
    from collections import defaultdict
    n = len(vals)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    byval = defaultdict(list)
    for i, v in enumerate(vals):
        byval[v].append(i)

    ans = n
    for v in sorted(byval):
        for u in byval[v]:
            for w in adj[u]:
                if vals[w] <= v:
                    ru, rw = find(u), find(w)
                    if ru != rw:
                        parent[ru] = rw
        cnt = defaultdict(int)
        for u in byval[v]:
            cnt[find(u)] += 1
        for c in cnt.values():
            ans += c * (c - 1) // 2
    return ans
